WordHunterWoW_QuestEN[7871] = { title = "Vanquish the Invaders!", description = "Beyond this tunnel you will find a field of strife and turmoil, young <class>. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, <name>, and I shall reward you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove." }
WordHunterWoW_QuestEN[7872] = { title = "Vanquish the Invaders!", description = "Beyond this tunnel you will find a field of strife and turmoil, young <class>. The Horde continue to decimate our sacred forest, cutting down the evergreen foliage to power their machines of war.\n\nEnter Warsong Gulch and defend Silverwing Hold. Push back the invading Horde forces!\n\nDo this, and earn a talisman of merit.  Bring me such a talisman, <name>, and I shall reward you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove." }
