WordHunterWoW_QuestEN[7905] = { title = "The Darkmoon Faire", description = "The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told!\n\nIf you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels!\n\nJust hand your voucher to Gelvas Grimegate located inside the Faire.\n\nRight now, the entrance to the Faire is outside Goldshire, in Elwynn Forest.", objectives = "Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival." }
WordHunterWoW_QuestEN[7907] = { title = "Darkmoon Beast Deck", description = "Now that you have gathered all of the Beast cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Beast Deck to the Darkmoon Faire when it comes to town." }
