WordHunterWoW_QuestEN[7926] = { title = "The Darkmoon Faire", description = "The Darkmoon Faire is coming! Experience our thrilling games, win fabulous prizes, have your fortune told!\n\nIf you act right now, you can redeem this voucher for free prize tickets and a copy of the world-famous Darkmoon Adventurer's Guide to help you identify treasures in your travels!\n\nJust hand your voucher to Gelvas Grimegate located inside the Faire.\n\nRight now, the entrance to the Faire is outside Thunder Bluff in Mulgore!", objectives = "Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival." }
WordHunterWoW_QuestEN[7927] = { title = "Darkmoon Portals Deck", description = "Now that you have gathered all of the Portal cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Portals Deck to the Darkmoon Faire when it comes to town." }
WordHunterWoW_QuestEN[7928] = { title = "Darkmoon Warlords Deck", description = "Now that you have gathered all of the Warlord cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.   You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Warlords Deck to the Darkmoon Faire when it comes to town." }
WordHunterWoW_QuestEN[7929] = { title = "Darkmoon Elementals Deck", description = "Now that you have gathered all of the Elemental cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Elementals Deck to the Darkmoon Faire when it comes to town." }
