WordHunterWoW_QuestEN[8114] = { title = "Control Four Bases", description = "<name>, you have taken the battle of Arathi Basin to our enemies and earned great honors in that field of battle.  You have shown us your worth as a <class>, and you have shown our enemies that we will not submit to their villainy!\n\nBecause of your proven value to us, I have a difficult task for you.  I want you to take and hold at least four of the bases in Arathi Basin.  If you can do that, then we will not only secure critical resources, we will show the Horde our dominance!\n\nGo, <name>, and good fortune.", objectives = "Enter Arathi Basin, capture and control four bases at the same time, and then return to Field Marshal Oslight at Refuge Pointe." }
WordHunterWoW_QuestEN[8115] = { title = "Control Five Bases", description = "<name>, battling for the resources of Arathi Basin is a bloody undertaking.  Your services to the League of Arathor are as needed as they are appreciated.\n\nAnd we have one more task for you.\n\nThe League wishes to make one strong push against the Defilers' occupation of Arathi Basin.  We want them driven out of every strategic point on the battlefield!\n\nIt will not be easy, but if anyone can get it done, it is you.", objectives = "Control 5 bases in Arathi Basin at the same time, then return to Field Marshal Oslight at Refuge Pointe." }
WordHunterWoW_QuestEN[8116] = { title = "Vision of Voodress", description = "", objectives = "" }
WordHunterWoW_QuestEN[8117] = { title = "Vision of Voodress", description = "", objectives = "" }
WordHunterWoW_QuestEN[8118] = { title = "Vision of Voodress", description = "", objectives = "" }
WordHunterWoW_QuestEN[8119] = { title = "The Unmarred Vision of Voodress", description = "", objectives = "" }
WordHunterWoW_QuestEN[8120] = { title = "The Battle for Arathi Basin!", description = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, <name>.  Report back to me when this task is complete.", objectives = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall." }
WordHunterWoW_QuestEN[8121] = { title = "Take Four Bases", description = "<name>, as the battles over Arathi Basin rage, news of your actions have reached many ears.  You are highly regarded among us, which gives me confidence that you will accomplish the mission I now have for you.\n\nIt is time to send a message to the League of Arathor.  We must show them that their holdings in Arathi Basin are tenuous and quickly lost.  We will show them this by holding, all at once, four strategic points in Arathi Basin.\n\nSucceed in this, <name>, and earn great respect among the Defilers.", objectives = "Hold four bases at the same time in Arathi Basin, and then return to Deathmaster Dwire in Hammerfall." }
WordHunterWoW_QuestEN[8122] = { title = "Take Five Bases", description = "It is difficult to see, so deep we are in the conflict, but our spies report a weakening in the League of Arathor's resolve.  We must use this window and strike a brutal blow against them!  Return to Arathi Basin and throw yourself against our foes.  Curse them and kill them and control all five strategic bases!  Send their soldiers screaming and bleeding from the front lines, with stories of your cruelty on their mewling lips.\n\nDo this, and score a great victory for the Defilers.", objectives = "Hold five bases in Arathi Basin at the same time, then return to Deathmaster Dwire in Hammerfall." }
WordHunterWoW_QuestEN[8123] = { title = "Cut Arathor Supply Lines", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, <name>.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall." }
WordHunterWoW_QuestEN[8124] = { title = "More Resource Crates", description = "", objectives = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall." }
