WordHunterWoW_QuestEN[8181] = { title = "Confront Yeh'kinya", description = "My delvings into the Mosh'aru Tablets bear grim news, <name>.  Hakkar's true form, the god himself, can be born again through the very egg into which you captured him.  Yeh'kinya told you it was to contain his evil, but it is to recreate it!  The troll has led you astray!\n\nGo to Yeh'kinya and demand the egg from him.  Pray that it is not too late to stop Hakkar's return!", objectives = "Speak with Yeh'kinya." }
WordHunterWoW_QuestEN[8182] = { title = "The Hand of Rastakhan", description = "<name>, our worst fears have come.  Legend speaks of the Soulflayer ruling the ancient troll world through evil and terror, and his power was absolute.  If he cannot be stopped now, then his new reign may spread across all of Azeroth!\n\nThere is a contingent of Zandalarian trolls who may help us stem this tide of darkness.  They have camped on Yojamba Isle, off the coast of Stranglethorn, west of the ruins of Zul'Kunda.  Speak with their leader, Molthor, and pray he knows how to defeat Hakkar.", objectives = "Speak with Molthor in Stranglethorn." }
WordHunterWoW_QuestEN[8183] = { title = "The Heart of Hakkar", description = "The Heart of Hakkar burns from within.  Although the Soulflayer is defeated, the kernel of his power yet remains in this cursed organ.", objectives = "Bring the Heart of Hakkar to Molthor on Yojamba Isle." }
