WordHunterWoW_QuestEN[8442] = { title = "Conquering Arathi Basin", description = "", objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds." }
WordHunterWoW_QuestEN[8443] = { title = "Conquering Arathi Basin", description = "", objectives = "Bring 3 Arathi Basin Mark of Honor to a Horde Warbringer outside the battlegrounds." }
WordHunterWoW_QuestEN[8446] = { title = "Shrouded in Nightmare", description = "Corruption seeps from this object.\n\nThere may be a link between this object and the dragons coming forth from the Dream. You must find someone that can decipher the meaning of this item. Perhaps the druids of the Moonglade or Cenarion Hold could assist you further.", objectives = "Find someone capable of deciphering the meaning behind the Nightmare Engulfed Object.\nPerhaps a druid of great power could assist you." }
WordHunterWoW_QuestEN[8447] = { title = "Waking Legends", description = "The waters of Lake Elune'ara should dissolve the nightmares engulfing this object. Give me a moment to perform the cleansing, {name}.", objectives = "Wait for Keeper Remulos at the Moonglade to cleanse the Nightmare Engulfed Object." }
WordHunterWoW_QuestEN[8460] = { title = "Timbermaw Ally", description = "The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe. For this reason, the Timbermaw furbolg trust very few.\n\nAre you interested in proving yourself? Drive back the corrupted Deadwood tribe of Felwood and we may one day consider you an ally. You'll find the first Deadwood tribe - warriors, pathfinders and gardeners - to my west.", objectives = "Grazle wants you to prove yourself by killing 6 Deadwood Warriors, 6 Deadwood Pathfinders, and 6 Deadwood Gardeners. Return to him in southern Felwood near the Emerald Sanctuary when you are done." }
WordHunterWoW_QuestEN[8461] = { title = "Deadwood of the North", description = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  It saddens me that we must fight our own brethren.\n\nPlease, <name> - I ask you to do what must be done.  Simply spare me the details; such troublesome images upset me far too much.", objectives = "Nafien would like you to kill 6 Deadwood Den Watchers, 6 Deadwood Avengers, and 6 Deadwood Shamans. Return to him in northern Felwood near the entrance to Timbermaw Hold." }
WordHunterWoW_QuestEN[8462] = { title = "Speak to Nafien", description = "Perhaps you are capable of handling a larger threat that we Timbermaw face.  You certainly have shown yourself capable here...\n\nAnother of my kind stands guard outside the entrance to Timbermaw Hold, along this road far to the north.  His name is Nafien; while he may appear to be a feral and unsavory beast, fear him not.  He only seeks aid against the malign forces that threaten our home.", objectives = "Travel north along the main road in Felwood and speak with the furbolg named Nafien. He stands guard outside the entrance to Timbermaw Hold." }
WordHunterWoW_QuestEN[8464] = { title = "Winterfall Activity", description = "The Timbermaw tend to stay to themselves, <name>.  While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible.\n\nThe Winterfall tribe as of late has become increasingly hostile towards us.  They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nI must ask you to thin their numbers as to lessen the threat against us.  Seek them out in Winterfall Village, far to the east of here.", objectives = "Salfa wants you to kill 8 Winterfall Shaman, 8 Winterfall Den Watchers, and 8 Winterfall Ursa. Salfa is located just outside the entrance to Timbermaw Hold in Winterspring." }
WordHunterWoW_QuestEN[8465] = { title = "Speak to Salfa", description = "The threat of corruption comes not only from the Deadwood furbolgs to the south, but also from the east and the Winterfall furbolgs of Winterspring.  If you wish to further aid us, speak with Salfa on the other side of the Hold, by the Winterspring entrance.  Follow the path to the left to reach it.\n\nBe warned - if my kind inside considers you hostile or hated, they will attack.  Travel as quick as you can, avoiding conflict.  To kill a Timbermaw - even in self defense - will only alienate you further.", objectives = "Travel through Timbermaw Hold and exit into Winterspring. Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold." }
WordHunterWoW_QuestEN[8466] = { title = "Feathers for Grazle", description = "", objectives = "Some of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers. Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw." }
WordHunterWoW_QuestEN[8467] = { title = "Feathers for Nafien", description = "", objectives = "Some of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers. Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw." }
WordHunterWoW_QuestEN[8469] = { title = "Beads for Salfa", description = "", objectives = "The Winterfall are known to carry spirit beads to ward against foul spirits. These beads have clearly failed in their purpose, as the Winterfall themselves are the agents of corruption. Bring to me these spirit beads from fallen Winterfall furbolgs; for every set of five you bring me, you will earn recognition amongst the Timbermaw." }
WordHunterWoW_QuestEN[8470] = { title = "Deadwood Ritual Totem", description = "You have found one of the Deadwood furbolg's ritual totems.  The totem itself is of non-descript construction, but a palpable sense of despair emanates from it.  If there were any object that might best exemplify the corruption that the Deadwood furbolg suffer under, this item would clearly be it.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.\n", objectives = "Take the Deadwood Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item. The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them." }
WordHunterWoW_QuestEN[8471] = { title = "Winterfall Ritual Totem", description = "You have found one of the Winterfall furbolg's ritual totems.  The totem itself is of non-descript construction, but it seems to emanate an almost tangible sense of dread and despair.  If many of the Winterfall furbolgs do indeed carry these, it certainly would go a long way in explaining their current condition.\n\nOne of the furbolgs inside Timbermaw Hold may have a use for such an item... that is, if you've earned their trust enough for them to speak with you.", objectives = "Take the Winterfall Ritual Totem inside Timbermaw Hold and see if one of the furbolgs there will find a use for the item. The Timbermaw will not speak with you unless you are of Neutral reputation or greater with them." }
WordHunterWoW_QuestEN[8481] = { title = "The Root of All Evil", description = "{name}, thanks to you we have devised a way to summon forth the root of all evil for the Winterfall tribe - the corrupting demon that dominates them!\n\nTake this torch to the mouth of Grolnar's personal cave and plant it there.  Doing so will force the demon to reveal itself and investigate.  This is when you and your allies must strike it down!  Only the essence of the fallen demon will begin the lengthy healing process of the Winterfall tribe... and the salvation of Timbermaw Hold.", objectives = "Plant the Demon Summoning Torch in the mouth of High Chief Winterfall's cave in the Winterfall furbolg village. Defeat the demon and retrieve the Essence of Xandivious for Gorn One Eye in Timbermaw Hold." }
WordHunterWoW_QuestEN[8484] = { title = "The Brokering of Peace", description = "Your deeds go beyond the tale of a simple hero, <name>.  If you are a representative of your people, then your people are ones we would work to make peace with.\n\nPlease - take this offering to the dwarven king that resides in a mountain of iron; I believe you call this city Ironforge.  In times past, he had tried to make contact with us on behalf of his Alliance.  It is now only fitting to acknowledge you as the key in your Alliance's efforts in brokering peace.", objectives = "Bring the Timbermaw Offering of Peace to King Magni Bronzebeard in Ironforge." }
WordHunterWoW_QuestEN[8485] = { title = "The Brokering of Peace", description = "Your deeds go beyond the tale of a simple hero, <name>.  If you are a representative of your people, then your people are ones we would work to make peace with.\n\nPlease - take this offering to the orcish warchief that resides in the lands of Durotar; I believe you call this city Orgrimmar.  In times past, he had tried to make contact with us on behalf of his Horde.  It is now only fitting to acknowledge you as the key in your Horde's efforts in brokering peace.", objectives = "Bring the Timbermaw Offering of Peace to Thrall in Orgrimmar." }
WordHunterWoW_QuestEN[8492] = { title = "The Alliance Needs Copper Bars!", description = "Hey there, {class}, you look fit enough to contribute to the war effort! We need all of the help that we can get here to put together the materiel needed for the Ahn'Qiraj War and it's your lucky day.\n\nI'm collecting copper bars in stacks of twenty. It's for a worthy cause, what do you say? Do you think you could help out the Alliance?", objectives = "Bring 20 Copper Bars to Sergeant Stonebrow at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8493] = { title = "The Alliance Needs More Copper Bars!", description = "Back again <class>? Outstanding! We still need more stacks of copper bars if you can procure them for the Ahn'Qiraj war effort.  Will you help us out?You will receive:", objectives = "Bring 20 copper bars to Sergeant Stonebrow at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8494] = { title = "The Alliance Needs Iron Bars!", description = "Well hello there, Mr. Fancypants, aren't you a sight for sore eyes. In case you hadn't heard while you were out there \"adventuring\", the Alliance has been gearing up for a war in Ahn'Qiraj and is in need of iron bars... a whole mess of 'em. Bring them to me in stacks of twenty. We can count on you, right, {class}?", objectives = "Bring 20 Iron Bars to Corporal Carnes at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8495] = { title = "The Alliance Needs More Iron Bars!", description = "Back so soon? Stop making me re-evaluate my low opinion of you <class>, you're making me feel all gooey inside. So, as you can tell we still don't have enough iron bars for all of the weapons, armor, steam tanks and whatnot that need building for the bug hunt. Think you have it in you to bring back another stack of twenty iron bars in between all of those trips to Zul'Gurub, or wherever it is that you kids hang out these days?You will receive:", objectives = "Bring 20 iron bars to Corporal Carnes at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8496] = { title = "Bandages for the Field", description = "Our supply of bandages in the battlefield is running dangerously low after the recent casualties we have incurred.  Obtain a batch of first-aid supplies and deliver them to Windcaller Proudhorn in Cenarion Hold.You will receive:", objectives = "Bring 30 Heavy Runecloth Bandages, 30 Heavy Silk Bandages and 30 Heavy Mageweave Bandages to Windcaller Proudhorn at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing X in order to complete this quest." }
WordHunterWoW_QuestEN[8497] = { title = "Desert Survival Kits", description = "With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.You will receive:", objectives = "Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Smoked Desert Dumplings to Calandrath at the inn in Cenarion Hold in Silithus. You must also bring Logistics Task Briefing I in order to complete this quest." }
WordHunterWoW_QuestEN[8498] = { title = "Twilight Battle Orders", description = "Our scouts have reported new battle orders being issued by the Twilight's Hammer leaders.  The orders are being distributed by Twilight Prophets under heavy escort.  Intercept the orders and bring them to Commander Mar'alith.", objectives = "Obtain the Twilight Battle Orders and bring them Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Tactical Task Briefing X in order to complete this quest." }
WordHunterWoW_QuestEN[8499] = { title = "The Alliance Needs Thorium Bars!", description = "It is very kind of you to inquire about the needs that the Alliance has. In addition to all of the other collection efforts underway, we are in need of a great quantity of thorium bars, which is the task that I am in charge of. The thorium will be used in the creation of many different things for the war, foremost of which is the construction of a battalion of steam tanks to be airlifted into Silithus as soon as they are completed. Can you aid us in this endeavor, {class}?", objectives = "Bring 20 Thorium Bars to Dame Twinbraid at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8500] = { title = "The Alliance Needs More Thorium Bars!", description = "It is so good to see you again <name>. I hope that you've been doing well. It's true that we are still in need of thorium bars. If you have them to spare I am collecting them for the Ahn'Qiraj war effort.You will receive:", objectives = "Bring 20 thorium bars to Dame Twinbraid at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8501] = { title = "Target: Hive'Ashi Stingers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of the airborne Hive'Ashi stingers.\n\nReport back to Commander Mar'alith after your task is completed.", objectives = "Kill 30 Hive'Ashi Stingers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing XII in order to complete this quest." }
WordHunterWoW_QuestEN[8502] = { title = "Target: Hive'Ashi Workers", description = "As the war effort mounts, the silithid presence in the area presents an ever increasing threat to our operations.  You've been selected to partake on an assault on Hive'Ashi where your primary target will consist of Hive'Ashi workers.\n\nReport back to Commander Mar'alith after your task is completed.", objectives = "Slay 30 Hive'Ashi Workers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing III in order to complete this quest." }
WordHunterWoW_QuestEN[8503] = { title = "The Alliance Needs Stranglekelp!", description = "So, {class}, did I already tell you about all of the fabulous uses stranglekelp has? I did? Oh well... in any case we need a lot of it, and when I say a lot, I mean A LOT! Do you think that you could help us out? I know that it means going without all of those wonderful things that you can make with it, but it's for a good cause!", objectives = "Bring 20 Stranglekelp to Private Draxlegauge at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8504] = { title = "The Alliance Needs More Stranglekelp!", description = "Well hello again there... what was it? Ah yes, <name>! Come to see if I still need more stranglekelp have you? Well, it's your lucky day, because the answer to that very important question is a very affirmative YES! Think you could gather up twenty more?You will receive:", objectives = "Bring 20 stranglekelp to Private Draxlegauge at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8505] = { title = "The Alliance Needs Purple Lotus!", description = "{class}, the purple lotus is a flower with a plentitude of uses. I am here at the request of the Alliance as an authority on those applications, to preserve the herbs collected and to ensure that their war effort acquires enough purple lotus to sustain whatever function they plan for it.\n\nI would like for you to travel out into the world and return to me with some of these flowers. Is that something that you can do?", objectives = "Bring 20 Purple Lotus to Master Nightsong at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8506] = { title = "The Alliance Needs More Purple Lotus!", description = "Welcome back <class>. Our collection grows, but even now we have a need for additional purple lotus. If it is still within your power to gather more of the herb, I entreat you to do so and return them to me here.You will receive:", objectives = "Bring 20 purple lotus to Master Nightsong at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8507] = { title = "Field Duty", description = "Greetings, <name>.  Before I assign you to more involved tasks in the war, you'll need to do your share of field duty.  \n\nYou will find Captain Blackanvil's Ironforge Brigade outside Hive'Zora.\n\nReport to him or his lieutenant, Janela Stouthammer and come back to me.  I shall have a more advanced assignment for you ready.\n\nOh and please do us a favor and stay away from the Orgrimmar Legion.  We've been forced to keep the two forces well apart from one another due to mutual animosity.", objectives = "Report for duty at the Ironforge Brigade post near Hive'Zora. Prepare your Unsigned Field Duty Papers and obtain Signed Field Duty Papers from Captain Blackanvil and return to Windcaller Kaldon at Cenarion Hold in Silithus.\nNote: Healing or casting beneficial spells on a member of the Ironforge Brigade will flag you for PvP." }
WordHunterWoW_QuestEN[8508] = { title = "Field Duty Papers", description = "", objectives = "" }
WordHunterWoW_QuestEN[8509] = { title = "The Alliance Needs Arthas' Tears!", description = "I'll keep it simple and to the point, {class}. The Alliance needs to collect a large quantity of Arthas' Tears for the Ahn'Qiraj war effort. Don't ask me what for; I'm just following orders. But I'd like you to gather up as many of the herbs as you can and bring them back to me here. Are you willing to do that?", objectives = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8510] = { title = "The Alliance Needs More Arthas' Tears!", description = "Ok, so it looks like I still need more Arthas' Tears. I would imagine that you will be able to find them in the general location that you gathered them up for me last time. The quicker we get these, the faster we can start up the offensive against the forces at Ahn'Qiraj.\n\nYou gonna help us out again <class>?You will receive:", objectives = "Bring 20 Arthas' Tears to Sergeant Major Germaine at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8511] = { title = "The Alliance Needs Light Leather!", description = "We Stoneflayers have a long history of being skinners, {class}. That's why the Alliance has asked my family to help out with the collection of light leather for the Ahn'Qiraj war effort. I'm here to see to it that the leather is tanned correctly for whatever they want to put it to use for. But we need your help.\n\nSince I have to be here doing that, I need you to go out and collect the skins, returning them to me here. What do you say, lad, will you give it a go?", objectives = "Bring 10 Light Leather to Bonnie Stoneflayer at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8512] = { title = "The Alliance Needs Light Leather!", description = "Good to see you again <name>. It does appear that we need more light leather for the creation of the various war materiel. If you could bring me a stack of ten that would be just perfect.You will receive:", objectives = "Bring 10 light leather to Bonnie Stoneflayer at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8513] = { title = "The Alliance Needs Medium Leather!", description = "Yes sir, I have been charged with collecting and tracking all of the medium leather gathered for the war effort. If you have the wherewithal to gather medium leather, from whatever source, then please bring them to me here. I sure would appreciate a hand with this if you can spare the time.", objectives = "Bring 10 Medium Leather to Private Porter at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8514] = { title = "The Alliance Needs More Medium Leather!", description = "Yes <sir/ma'am>, looks like we've collected $2063w pieces of medium leather to date. I know it's a lot to ask, but if you're still willing, I could use your help in attempting to put a dent in the rest of my quota.You will receive:", objectives = "Bring 10 medium leather to Private Porter at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8515] = { title = "The Alliance Needs Thick Leather!", description = "Oh boy, this is going to be great! {class}, the Ahn'Qiraj war effort is in full swing, and I've been put in charge of keeping track of all of the thick leather that comes in. We'll make tons of things with it, but first we need to get a ton of it. And I mean that literally! That's where you come in.\n\nSo, do you think you can go out there and bring me back a nice, fat stack of thick leather? Do yah, do yah?!", objectives = "Bring 10 Thick Leather to Marta Finespindle at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8516] = { title = "The Alliance Needs More Thick Leather!", description = "Yep, the stack's still not high enough. <name>, we still haven't reached our goal of $2071w thick leather. Just think of all the things that we can make with all of that leather! All kinds of armor and weapons. Stuff for inside the steam tanks and rifle scopes! Engineering goggles, and I bet if it ends up that we collect too much we could give the rest to the Horde for their zeppelins!\n\nYou gonna bring me back some more thick leather?You will receive:", objectives = "Bring 10 thick leather to Marta Finespindle at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8517] = { title = "The Alliance Needs Linen Bandages!", description = "The war at Ahn'Qiraj is going to be long and bloody. It is a very wise thing that the Alliance is doing by enlisting the aid of you, and those like you, to build up the materiel necessary before plunging headlong into conflict.\n\nI have been asked to head up the collection of linen bandages for the war, and I am hoping that you are going to assist me in amassing as many as we need. It is no light matter, but at least the linen bandages are the least difficult to create. Are you with us, {class}?", objectives = "Bring 20 Linen Bandages to Sentinel Silversky at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8518] = { title = "The Alliance Needs More Linen Bandages!", description = "Ever am I amazed by the selflessness exhibited when so many would instead turn to selfishness instead. <class>, I am still in need of a number of linen bandages before my assignment here is fulfilled. Will you aid me once more in the collection of those bandages?You will receive:", objectives = "Bring 20 linen bandages to Sentinel Silversky at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8519] = { title = "A Pawn on the Eternal Board", description = "As you regain your composure and focus your gaze, you notice that something stirs within the crystal. Upon closer inspection, you realize that you are looking into the past... a memory... long forgotten.", objectives = "Learn all that you can of the past, then speak with Anachronos at the Caverns of Time in Tanaris." }
WordHunterWoW_QuestEN[8520] = { title = "The Alliance Needs Silk Bandages!", description = "With the Ahn'Qiraj War looming we need to do everything that we can to see to it that our soldiers have everything that they need. We're doing just that right here. For my part I've been placed in charge of seeing to it that we collect enough silk bandages.\n\nDo you think you can help me out, {class}?", objectives = "Bring 20 Silk Bandages to Nurse Stonefield at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8521] = { title = "The Alliance Needs More Silk Bandages!", description = "It is very kind of you to offer to help me again <class>. It looks like we've collected $2082w silk bandages, so we'll need more.You will receive:", objectives = "Bring 20 silk bandages to Nurse Stonefield at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8522] = { title = "The Alliance Needs Runecloth Bandages!", description = "Argue the merits of the war if you will, {class}, but it has already been set in motion. Look around you at your family and friends, and then ask yourself what it is that you can do to see to it that if they are involved, they will have every advantage to survive the conflagration.\n\nTo that end, I am collecting runecloth bandages here from whatever source. Would you like to make a donation?", objectives = "Bring 20 Runecloth Bandages to Keeper Moonshade at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8523] = { title = "The Alliance Needs More Runecloth Bandages!", description = "So it is that we come to discuss pressing matters yet again <class>. Once more I thank you for your previous efforts; it is not everyone who would give so selflessly. But there is still more work to do.\n\n<name>, will you once more collect runecloth bandages and return them to me here?You will receive:", objectives = "Bring 20 runecloth bandages to Keeper Moonshade at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8524] = { title = "The Alliance Needs Rainbow Fin Albacore!", description = "Hey there, friend! If I were to say to you, 'Don't you think that soldiers should have food to eat like anyone else?', you would of course reply, 'yes'. I agree with you 110%! I'm glad we're in accord. All I need for you to do is to head out there, fish up a whole bunch of raw rainbow fin albacore, and then cook it all up and bring it back to me right here. Mmm, mmm, I can taste it already.", objectives = "Bring 20 Rainbow Fin Albacore to Slicky Gastronome at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8525] = { title = "The Alliance Needs More Rainbow Fin Albacore!", description = "What! You again? Well I'll be a monkey's uncle... except that I'm a gnome. Slicky Gastronome to be precise! So you're back to help out again eh? Well, I can't say as I blame you. Don't you just love the smell of all of that food? <drool>\n\nEnough loitering! Get out there and bring me back more rainbow fin albacore!You will receive:", objectives = "Bring 20 rainbow fin albacore to Slicky Gastronome at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8526] = { title = "The Alliance Needs Roast Raptor!", description = "Oh, how's it going, {class}? I see that you're interested in maybe gathering up food for the coming war at Ahn'Qiraj? Somehow my dad thought that it would be a good learning experience for me if I were to volunteer to help out here. Big mistake. I don't even like to eat meat.\n\nAnyway, if you feel like it, you could bring me back a lot of roast raptor. Apparently that's what all of the soldiers are going to want.", objectives = "Bring 20 Roast Raptor to Sarah Sadwhistle at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8527] = { title = "The Alliance Needs More Roast Raptor!", description = "Hi again <class>. I can tell you're very excited about all of this. So I suppose you want to bring me another twenty roast raptor. Great. Well you do that. I guess I'll see you when you get back.You will receive:", objectives = "Bring 20 roast raptor to Sarah Sadwhistle at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8528] = { title = "The Alliance Needs Spotted Yellowtail!", description = "It may not seem heroic to gather up cooked fish, but do not underestimate the value of preparation, young {class}. Soldiers need to eat like anyone else, and we're here to do our part to make sure they have what they need once the war in Ahn'Qiraj commences.\n\nAccordingly, I am stockpiling spotted yellowtail, a versatile source of sustenance that stores well and can be used in many different dishes. It also doesn't have the odor of some other saltwater fish. Are you willing to aid me in this endeavor?", objectives = "Bring 20 Spotted Yellowtail to Huntress Swiftriver at the Military Ward in Ironforge." }
WordHunterWoW_QuestEN[8529] = { title = "The Alliance Needs More Spotted Yellowtail!", description = "If you're still willing I'd like to send you back out to bring in another haul of spotted yellowtail, <name>. I'd imagine with the expertise you gained the first time out that this catch should be much faster and easier. Are you game?You will receive:", objectives = "Bring 20 spotted yellowtail to Huntress Swiftriver at the airfield in Dun Morogh." }
WordHunterWoW_QuestEN[8532] = { title = "The Horde Needs Copper Bars!", description = "So glad that you've decided to help out here. Not everyone would, so I need to make sure you understand what it is that I need. Copper bars, not copper ore. We don't have the time or people to do all of the smelting ourselves, so if you would be so kind as to take care of that, your efforts will be duly noted. Is that something that you can handle, {class}?", objectives = "Bring 20 Copper Bars to Miner Cromwell at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8533] = { title = "The Horde Needs More Copper Bars!", description = "Back so soon? You'll be a real miner in no time <class>. So, you already know the drill; I need you to go out, mine up a mess of copper ore, smelt it into bars and bring it back to me here. I know that's something you're capable of, the question is, are you willing?You will receive:", objectives = "Bring 20 copper bars to Miner Cromwell in Durotar." }
WordHunterWoW_QuestEN[8534] = { title = "Hive'Zora Scout Report", description = "We've sent our best scouts deep into the silithid hives to gather intelligence.  Scout Azenel has been watching the silithid movements at Hive'Zora for several days now.  Find her and obtain a written report.  We need to be able to act on that information as soon as possible, <name>.", objectives = "Contact Cenarion Scout Azenel inside Hive'Zora and return the Hive'Zora Scout Report to Windcaller Proudhorn at Cenarion Hold. You must also bring Tactical Task Briefing VI in order to complete this quest." }
WordHunterWoW_QuestEN[8535] = { title = "Hoary Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy a Hoary Templar and report to Bor Wildmane.", objectives = "Summon and slay a Hoary Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing IV in order to complete this quest." }
WordHunterWoW_QuestEN[8536] = { title = "Earthen Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy an Earthen Templar and report to Bor Wildmane.", objectives = "Summon and slay an Earthen Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing III in order to complete this quest." }
WordHunterWoW_QuestEN[8537] = { title = "Crimson Templar", description = "The Twilight's Hammer and the elemental nobles they worship present a formidable threat to our operations in Silithus.  With the new enemies we're facing inside Ahn'Qiraj, we cannot afford to lower our guard to our enemies outside.\n\nFind a way to summon and destroy a Crimson Templar and report to Bor Wildmane.", objectives = "Summon and slay a Crimson Templar and report back to Bor Wildmane in Cenarion Hold. You must also bring Tactical Task Briefing II in order to complete this quest." }
WordHunterWoW_QuestEN[8538] = { title = "The Four Dukes", description = "The links between the Twilight's Hammer and the Abyssal Council are proving to be more important than we had expected.\n\nWe believe the elemental nobles known as the Abyssal Dukes are one of the primary force organizing the Twilight's Hammer cultists.  Find a way to lure the four Abyssal Dukes into our plane of existence and destroy them!\n\nYour dedication and prowess in past assignments have led us to choose you for this particular assignment.  We are certain you will succeed in this endeavor.You will receive:", objectives = "Find a way to summon and slay the Duke of Cynders, the Duke of Fathoms, the Duke of Zephyrs and the Duke of Shards and report back to Commander Mar'alith in Cenarion Hold. You must also bring Tactical Task Briefing V in order to complete this quest." }
WordHunterWoW_QuestEN[8539] = { title = "Target: Hive'Zora Hive Sisters", description = "Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora hive sisters.  Report back to Commander Mar'alith after completing your task.", objectives = "Slay 30 Hive'Zora Hive Sisters and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing V in order to complete this quest." }
WordHunterWoW_QuestEN[8540] = { title = "Boots for the Guard", description = "The mounted division of the Cenarion Hold guard is in short supply of ornate mithril boots.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.You will receive:", objectives = "Bring 3 Ornate Mithril Boots to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing II in order to complete this quest." }
WordHunterWoW_QuestEN[8541] = { title = "Grinding Stones for the Guard", description = "The Cenarion Hold guard is in short supply of grinding stones.  Procure a batch and deliver them immediately to Captain Vish Kozus in Cenarion Hold.", objectives = "Bring 10 Dense Grinding Stones, 10 Solid Grinding Stones and 10 Heavy Grinding Stones to Vish Kozus, Captain of the Guard at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing III in order to complete this quest." }
WordHunterWoW_QuestEN[8542] = { title = "The Horde Needs Tin Bars!", description = "Lok'tar, {race}, I'm sure you already know that we're going to war at Ahn'Qiraj with the insects. But first the Warchief has decided that we're going to do something called 'prepare'. Though I'd rather be sharpening weapons and hammering armor into shape, I'm proud to have been chosen to be in charge of tin bar collection here. But I cannot do that without your help.\n\nSo I need you to go out and make tin bars and bring them back to me here. I think I'm going to need more than I can count.\n", objectives = "Bring 20 Tin Bars to Grunt Maug at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8543] = { title = "The Horde Needs More Tin Bars!", description = "Very good, I see that you are serious about the war. I'm a little edgy waiting for it to start though, which means I'm going to get angry if you don't start bringing in the goods faster. Maybe I can just practice on you instead.\n\nHar! Maybe not, 'cuz then who would bring me back the tin bars?You will receive:", objectives = "Bring 20 tin bars to Grunt Maug in Durotar." }
WordHunterWoW_QuestEN[8544] = { title = "Conqueror's Spaulders", description = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!", objectives = "Bring the Qiraji Bindings of Command, 2 Idols of Night, 5 Stone Scarabs and 5 Clay Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest." }
WordHunterWoW_QuestEN[8545] = { title = "The Horde Needs Mithril Bars!", description = "{class}, the war it is comin' and the only thing we can do is prepare for it. That be where you and I can help each other, mon. Ya see, they put me in charge of collectin' all the mithril bars we be needin' ta build for all the things we gonna need. An I still be needin' more!\n\nSo, I be hopin' that you can get out there an mine us up some mithril, then smelt it into bars. Sound like something you can do for us?", objectives = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8546] = { title = "The Horde Needs More Mithril Bars!", description = "", objectives = "Bring 20 Mithril Bars to Senior Sergeant T'kelah at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8548] = { title = "Volunteer's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, <name>.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.Upon completion of this quest you will gain:", objectives = "Bring 5 Cenarion Combat Badges, 3 Cenarion Logistics Badges and 7 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Friendly reputation with Cenarion Circle to be able to complete this quest." }
WordHunterWoW_QuestEN[8549] = { title = "The Horde Needs Peacebloom!", description = "It is said that every generation must face a defining trial. I fear the Ahn'Qiraj War will be the crucible in which our mettle is tested. So we prepare, and in so doing find what we are made of.\n\nI have volunteered to help the Horde by gathering as much peacebloom as possible, so that it can be made into potions for the war. I hope that you are here to lend me your aid. If so, then I need you to bring back to me a good quantity of the herb. Will you assist me, {class}?", objectives = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8550] = { title = "The Horde Needs Peacebloom!", description = "", objectives = "Bring 20 Peacebloom to Herbalist Proudfeather at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8551] = { title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", objectives = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay." }
WordHunterWoW_QuestEN[8552] = { title = "The Monogrammed Sash", description = "This fine sash has the letters \"HS\" embroidered along its hem.", objectives = "Return the Monogrammed Sash to its owner." }
WordHunterWoW_QuestEN[8553] = { title = "The Captain's Cutlass", description = "After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.", objectives = "Speak with Sprogger." }
WordHunterWoW_QuestEN[8554] = { title = "Facing Negolash", description = "Negolash is a hungry giant.\n\nWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!\n\nIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!", objectives = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\nKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn." }
WordHunterWoW_QuestEN[8555] = { title = "The Charge of the Dragonflights", description = "", objectives = "" }
WordHunterWoW_QuestEN[8556] = { title = "Signet of Unyielding Strength", description = "The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.\n\nThe gems that adorn Qiraji idols would work quite well, as their quality is superior.\n\nBring me the ring and idols and I'll create a powerful ring for you, {class}.", objectives = "Bring 1 Qiraji Magisterial Ring, 2 Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest." }
WordHunterWoW_QuestEN[8557] = { title = "Drape of Unyielding Strength", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, {name}.  I can make you a protective item that'll be of assistance in the fight against our enemy, {class}.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", objectives = "Bring 1 Qiraji Martial Drape, 2 Onyx Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest." }
WordHunterWoW_QuestEN[8558] = { title = "Sickle of Unyielding Strength", description = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, {name}, and I will make you a powerful weapon from the finest Qiraji materials.", objectives = "Bring 1 Qiraji Spiked Hilt, 2 Alabaster Idols, 5 Crystal Scarabs and 5 Stone Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest." }
WordHunterWoW_QuestEN[8559] = { title = "Conqueror's Greaves", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", objectives = "Bring the Qiraji Bindings of Command, 2 Idols of War, 5 Ivory Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu." }
WordHunterWoW_QuestEN[8560] = { title = "Conqueror's Legguards", description = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.", objectives = "Bring Ouro's Intact Hide, 2 Idols of Death, 5 Bronze Scarabs and 5 Ivory Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest." }
WordHunterWoW_QuestEN[8561] = { title = "Conqueror's Crown", description = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, <name>.  I will give you a headpiece of unmatched power.", objectives = "Bring Vek'nilash's Circlet, 2 Idols of the Sun, 5 Stone Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest." }
WordHunterWoW_QuestEN[8562] = { title = "Conqueror's Breastplate", description = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!", objectives = "Bring the the Carapace of the Old God, 2 Idols of War, 5 Silver Scarabs and 5 Bone Scarabs to Vethsera inside Ahn'Qiraj. You must also attain Honored reputation with the Brood of Nozdormu to complete this quest." }
WordHunterWoW_QuestEN[8565] = { title = "Past Victories in Arathi", description = "", objectives = "" }
WordHunterWoW_QuestEN[8566] = { title = "Past Victories in Arathi", description = "", objectives = "" }
WordHunterWoW_QuestEN[8567] = { title = "Past Victories in Warsong Gulch", description = "", objectives = "" }
WordHunterWoW_QuestEN[8568] = { title = "Past Victories in Warsong Gulch", description = "", objectives = "" }
WordHunterWoW_QuestEN[8569] = { title = "Past Efforts in Warsong Gulch", description = "", objectives = "" }
WordHunterWoW_QuestEN[8570] = { title = "Past Efforts in Warsong Gulch", description = "", objectives = "" }
WordHunterWoW_QuestEN[8572] = { title = "Veteran's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, <name>.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.You will be able to choose one of these rewards:", objectives = "Bring 7 Cenarion Combat Badges, 4 Cenarion Logistics Badges and 4 Cenarion Tactical Badges to Vargus at Cenarion Hold in Silithus. You must also attain Honored reputation with Cenarion Circle to be able to complete this quest." }
WordHunterWoW_QuestEN[8573] = { title = "Champion's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show, <name>.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.You will be able to choose one of these rewards:", objectives = "Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 20 Cenarion Tactical Badges and 1 Mark of Cenarius to Vargus at Cenarion Hold in Silithus. You must also attain Exalted reputation with Cenarion Circle to be able to complete this quest." }
WordHunterWoW_QuestEN[8574] = { title = "Stalwart's Battlegear", description = "The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show, <name>.\n\nYou'd be wise to hold on to them.  As you prove your loyalty to our organization I can offer you some of the gear we reserve for our closest allies in exchange for those badges.You will be able to choose one of these rewards:", objectives = "Bring 15 Cenarion Combat Badges, 20 Cenarion Logistics Badges, 17 Cenarion Tactical Badges and 1 Mark of Remulos to Vargus at Cenarion Hold in Silithus. You must also attain Revered reputation with Cenarion Circle to be able to complete this quest." }
WordHunterWoW_QuestEN[8575] = { title = "Azuregos's Magical Ledger", description = "You cannot understand a single word on this ledger. You don't even know what language it is written in!", objectives = "Deliver Azuregos's Magical Ledger to Narain Soothfancy in Tanaris." }
WordHunterWoW_QuestEN[8576] = { title = "Translating the Ledger", description = "", objectives = "" }
WordHunterWoW_QuestEN[8577] = { title = "Stewvul, Ex-B.F.F.", description = "If I am to translate anything, I will need my scrying goggles. Unfortunately, those were stolen quite some time ago by my ex-best friend forever, Stewvul. He broke my heart in five places and then left me here to rot.\n\nWith the help of my trusty crystal ball, I've isolated his whereabouts to either the Greymane Wall in Silverpine or what appears to be a portal world in the Outland that is currently being overrun by the Burning Legion. You're going to have to track him down and get my goggles back, <name>!", objectives = "Narain Soothfancy wants you to find his ex-best friend forever (BFF), Stewvul, and take back the scrying goggles that Stewvul stole from him." }
WordHunterWoW_QuestEN[8578] = { title = "Scrying Goggles? No Problem!", description = "<You hear a sigh of relief escape the crate.>\n\nYou just want his scrying goggles? Great! That will be no problem... Just give me a minute to... Hey! Where the... Dagnabbit!\n\nWell, there's some bad news and some worse news. The bad news is that I lost the goggles. The worse news is that I lost them when I was nosing around in the Molten Core last month. Yep, the Molten Core... I guess that concludes our business! Bye!", objectives = "Find Narain's Scrying Goggles and return them to Narain Soothfancy in Tanaris." }
WordHunterWoW_QuestEN[8579] = { title = "Mortal Champions", description = "We sense the presence of our enslaved brethren deeper inside Ahn'Qiraj; yet not even an army of dragons would be enough to rescue them, {race}.\n\nThe same spell that imprisoned them would place us firmly under C'Thun's control should we come any closer to him.\n\nThe Old God has foreseen our arrival.  All hope is lost.  What difference could a mere mortal like you possibly make?", objectives = "" }
WordHunterWoW_QuestEN[8580] = { title = "The Horde Needs Firebloom!", description = "Hey, {class}. Ya you, mon! There be a whole mess of firebloom the Horde thinkin' they need for this Ahn'Qiraj war effort. Maybe they put it in nice things that go boom? Maybe they give it to the Alliance as fuel for their steam tanks? Who knows? Not Pele'keiki!\n\nPele'keiki know this though... he know you gonna help him out and bring back lots of the firebloom, right, mon?", objectives = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8581] = { title = "The Horde Needs More Firebloom!", description = "", objectives = "Bring 20 Firebloom to Batrider Pele'keiki at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8582] = { title = "The Horde Needs Purple Lotus!", description = "The purple lotus, {class}, is a reagent in a great many potions, elixirs and oils, some of which will be of use to us at Ahn'Qiraj. We're going to need to create an immense number of those potions for the war effort. And I'm going to experiment to find more uses for the lotus as well. But to do all of that I'm going to need a great quantity of the flower.\n\nThat's where you come in. Go out into the field and collect up as many purple lotuses as you can. Is this something that you are willing to do for us?", objectives = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8583] = { title = "The Horde Needs More Purple Lotus!", description = "", objectives = "Bring 20 Purple Lotus to Apothecary Jezel at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8584] = { title = "Never Ask Me About My Business", description = "If there is one thing that you should know about me, it is this: NEVER ask me about my business! I work with things you simply cannot understand. Like for example: Do you know what a psychotronic muzzledorf is? Of course you don't! And that's why we leave the planning to me and the fetching to you.\n\nAs I said earlier, if this is going to work, we're going to need a 500 pound chicken.\n\nHead to Gadgetzan and speak with Dirge Quikcleave - he'll get you started on finding a suitable specimen.", objectives = "Narain Soothfancy in Tanaris wants you to speak with Dirge Quikcleave in Gadgetzan." }
WordHunterWoW_QuestEN[8585] = { title = "The Isle of Dread!", description = "Legend has it that the chimaerok of the Isle of Dread in Feralas have the most succulent and tender vittles in existence! Now these chimaerok also have a daddy who, with proper preparation, may or may not look like a 500 pound chicken.\n\nHead to the Isle of Dread and kill Lord Lakmaeran and bring me his fresh carcass. That should satisfy the gnome. To satisfy me, you'll need to get your hands on some chimaerok tenderloin.\n\nDo this and you'll have your 500 pound chicken and a little something extra.", objectives = "Recover Lakmaeran's Carcass and 20 Chimaerok Tenderloins for Dirge Quikcleave in Tanaris." }
WordHunterWoW_QuestEN[8586] = { title = "Dirge's Kickin' Chimaerok Chops", description = "My recipe is complete! What I need from you now is some rocket fuel and deeprock salt. I'll handle the spices and the meat you brought me will cover the rest.\n\nAfter you bring me what I asked for, the chicken will be ready to take back to Narain.", objectives = "Dirge Quikcleave in Gadgetzan wants you to bring him 20 Goblin Rocket Fuel and 20 Deeprock Salt." }
WordHunterWoW_QuestEN[8587] = { title = "Return to Narain", description = "I'm a goblin of my word, kid. Here's your 500 pound chicken.\n\nWhat a gnome wants with a 500 pound chicken, I'll never know...\n\n<Dirge grumbles something unintelligible.>\n\nProbably to sleep in it... Dirty gnomes...", objectives = "Deliver the 500 Pound Chicken to Narain Soothfancy in Tanaris." }
WordHunterWoW_QuestEN[8588] = { title = "The Horde Needs Heavy Leather!", description = "Since we're preparing for war, it might be best if we get all of the goods we need first, don't you think, mon? One of the staples of the war materiel that we're producing is heavy leather. We'll use it for just about everything, from reinforcement to armor, and good old plain tarps too.\n\nBut first we need to get our hands on more of it. That's your job, {class}. Sharpen your knife and bring me back a bundle. Then we'll talk further.", objectives = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8589] = { title = "The Horde Needs More Heavy Leather!", description = "", objectives = "Bring 10 Heavy Leather to Skinner Jamani at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8590] = { title = "The Horde Needs Thick Leather!", description = "I'm glad that you decided to speak to me about this, {class}. It looks like the Horde's preparations for the upcoming Ahn'Qiraj War are in full swing. But you and I still need to do our part.\n\nI've been asked to collect a great number of thick leather skins for use in all manner of war materiel, and I need you to help me by going out there and gathering them up. There's honor and the gratitude of the Horde in it for you should you decide to help. Will you?", objectives = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8591] = { title = "The Horde Needs More Thick Leather!", description = "", objectives = "Bring 10 Thick Leather to Sergeant Umala at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8592] = { title = "Tiara of the Oracle", description = "The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity.  They mock me, knowing I cannot step further into their domain to save my brother Arygos.\n\nIn my visions I see their monstrous faces adorned by powerful crowns.  But I will have my revenge... I will transmute these symbols of Qiraji power to ones better suited to our needs.\n\nBring me the components I require, <name>.  I will give you a headpiece of unmatched power.", objectives = "Bring Vek'nilash's Circlet, 2 Idols of the Sage, 5 Silver Scarabs and 5 Bone Scarabs to Andorgos in Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest." }
WordHunterWoW_QuestEN[8593] = { title = "Trousers of the Oracle", description = "You seek to prove your worth to my kind, mortal?  Very well, perhaps we can be of mutual assistance.\n\nThe ancient sandworm, Ouro, is a being of legendary power.  He is rumored to have been created by the Old God himself as a mockery of life.\n\nHis skin is unnatural... thick, nearly impregnable, yet it's flexible and allows him to move with the speed and grace of a much smaller creature.\n\nBring me a sample of his skin along with other minor components and I shall craft you leggings of great power.", objectives = "Bring Ouro's Intact Hide, 2 Idols of Life, 5 Gold Scarabs and 5 Clay Scarabs to Kandrostrasz inside Ahn'Qiraj. You must also attain Friendly reputation with the Brood of Nozdormu to complete this quest." }
WordHunterWoW_QuestEN[8594] = { title = "Mantle of the Oracle", description = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!", objectives = "Bring the Qiraji Bindings of Command, 2 Idols of Rebirth, 5 Silver Scarabs and 5 Ivory Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest." }
WordHunterWoW_QuestEN[8595] = { title = "Mortal Champions", description = "", objectives = "" }
WordHunterWoW_QuestEN[8596] = { title = "Footwraps of the Oracle", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of command and other minor components by and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", objectives = "Bring the Qiraji Bindings of Command, 2 Idols of Death, 5 Bronze Scarabs and 5 Gold Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu." }
WordHunterWoW_QuestEN[8597] = { title = "Draconic for Dummies", description = "I knew that book would come in handy some day! Thankfully, I had the wit and foresight to stow it somewhere safe.\n\nDon't worry, it's in a place that nobody could ever hope to find it! I needed a gyrocopter just to get there the first time. Unfortunately I crashed it on the beach on my way back. It was through that accident that I gained these super-gnomish psychic powers!\n\nLook for my crashed gyrocopter somewhere on Land's End Beach and swim south from there! You'll know the spot when you see it!", objectives = "Find Narain Soothfancy's book, buried on an island in the South Seas." }
WordHunterWoW_QuestEN[8598] = { title = "rAnS0m", description = "<The text on this note is made up of various typefaces glued onto the parchment's surface.>\n\nWe've got your precious book, gnome. If you ever want to see it again, you'll do exactly as we ask.\n\n<A detailed set of instructions is listed, spanning 3 pages.>\n\nBring the money and come alone!", objectives = "Return the Ransom Letter to Narain Soothfancy in Tanaris." }
WordHunterWoW_QuestEN[8599] = { title = "Love Song for Narain", description = "It isn't often that I get visitors. As a matter of fact, the last time I had a visitor was when I rescued that dear, sweet gnome from the wreckage of the crashed flying machine.\n\n<Meridith gazes into nothingness, lost in a memory.>\n\nDo you know him? Narain? Narain Soothfancy? Oh it would mean so much to me if somebody would deliver a message to him for me. I must tell him how I feel! I know it's love! I just know it!\n\nCould you possibly deliver a message to Narain? I would be forever indebted to you!", objectives = "Take Meridith's Love Letter to Narain Soothfancy in Tanaris." }
WordHunterWoW_QuestEN[8600] = { title = "The Horde Needs Rugged Leather!", description = "I find that the fit of the knife in your palm is more important than the edge on it. Even the dullest blade can be made to cut if pressure is being properly applied through it, wouldn't you agree, {class}? But you and I don't have such problems as we maintain the sharpest of edges, yes? \n\nWell, no matter, I have a task for you. In service to the Horde, and to do your part for the Ahn'Qiraj war effort, I want you to return to me with a number of rugged leather skins. This is something that you will do, no?", objectives = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8601] = { title = "The Horde Needs More Rugged Leather!", description = "", objectives = "Bring 10 Rugged Leather to Doctor Serratus at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8602] = { title = "Stormcaller's Pauldrons", description = "It is said among us that the ornate shoulder armor worn by the mortal races started as an attempt to emulate the wings of a dragon.\n\nBring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!", objectives = "Bring the Qiraji Bindings of Dominance, 2 Idols of Life, 5 Gold Scarabs and 5 Crystal Scarabs to Andorgos in Ahn'Qiraj. You must also attain Neutral reputation with the Brood of Nozdormu to complete this quest." }
WordHunterWoW_QuestEN[8603] = { title = "Vestments of the Oracle", description = "The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj.  The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power.\n\nWhen the stars are favorable, he will lash out against all living beings with terrible wrath.  You must find him before then and find a way to bring his existence to an end.\n\nDo this and bring me a piece of his husk.  I shall grant you armor no mortal has ever worn... armor fit for one who has slain a god!", objectives = "Bring the the Husk of the Old God, 2 Idols of Death, 5 Stone Scarabs and 5 Crystal Scarabs to Vethsera inside Ahn'Qiraj. You must also attain Honored reputation with the Brood of Nozdormu to complete this quest." }
WordHunterWoW_QuestEN[8604] = { title = "The Horde Needs Wool Bandages!", description = "Greetings, {class}. In preparation for the war at Ahn'Qiraj, I am here coordinating the Horde's efforts at gathering wool bandages. Unfortunately, out in the field, our soldiers cannot afford to rely upon the presence of a healer to keep them alive. Trust me, I know first hand. Thus, we're putting together all of these first aid kits for them.\n\nIf you have the time, I need many wool bandages. Return them to me here and I will see to it that you are properly rewarded.", objectives = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8605] = { title = "The Horde Needs More Wool Bandages!", description = "", objectives = "Bring 20 Wool Bandages to Healer Longrunner at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8606] = { title = "Decoy!", description = "I've got it! Here's what we're going to do. I'm going to fill a sack up with rocks and you're going to make the drop. I know it said that I should make the delivery and I'm going to - sort of.\n\n<Narain looks you up and down.>\n\nYes, you will do just fine. Take this turban, robe, and sack of rocks and head to the drop off point in Winterspring.\n\nI've included everything you need in this special kit. When they show up to pick up the goods, snuff them out! That will teach them to mess with Narain!", objectives = "Narain Soothfancy in Tanaris wants you to travel to Winterspring and place the Bag of Gold at the drop off point documented by the booknappers." }
WordHunterWoW_QuestEN[8607] = { title = "The Horde Needs Mageweave Bandages!", description = "I trust that you are speaking to me because you are going to help with the collection I have been entrusted to? Good! By whatever means, and I do mean whatever, I wish for you to gather up a good number of mageweave bandages. Fresh would be nice, but not absolutely necessary. Return them to me here, {class}, and I will personally see to it that you are properly rewarded.", objectives = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8608] = { title = "The Horde Needs More Mageweave Bandages!", description = "", objectives = "Bring 20 Mageweave Bandages to Lady Callow at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8609] = { title = "The Horde Needs Runecloth Bandages!", description = "It appears inevitable that the Horde and Alliance are on a collision course for war at Ahn'Qiraj. Surprisingly, it is not a war with each other, but rather with the silithid, and whatever force controls them. Also surprisingly, both sides are doing their part to gather the resources necessary to wage a successful war.\n\nI am collecting runecloth bandages to distribute to the soldiers, but I won't be successful without assistance, hopefully yours. Is this something that you can aid me with, {class}?\n", objectives = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8610] = { title = "The Horde Needs More Runecloth Bandages!", description = "", objectives = "Bring 20 Runecloth Bandages to Stoneguard Clayhoof at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8611] = { title = "The Horde Needs Lean Wolf Steaks!", description = "I'm not standing here just to get a nice tan, {class}. There are war preparations to be made. If we're going to crush those bugs at Ahn'Qiraj then we need to be ready, and that includes food too!\n\nThey have me gathering and salting lean wolf steaks here for the upcoming war. But since I need to stay here to take care of all of this, I need you to go out, kill some wolves and then cook up the meat into lean wolf steaks and bring them back to me here. You got all that?", objectives = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8612] = { title = "The Horde Needs More Lean Wolf Steaks!", description = "", objectives = "Bring 20 Lean Wolf Steaks to Bloodguard Rawtar at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8613] = { title = "The Horde Needs Spotted Yellowtail!", description = "It be a nice day for fishin', don't'cha think mon? Good thing, cuz I be needin' a lot of fish it lookin' like. The Horde, they askin' me to be in charge of collectin' a ton of the spotted yellowtail for them. They say they needin' it for the war they getting' ready for at Ahn'Qiraj. I say to them I do the best I can. So I be needin' to get some help. You gonna be helpin' me, {class}?", objectives = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8614] = { title = "The Horde Needs More Spotted Yellowtail!", description = "", objectives = "Bring 20 Spotted Yellowtail to Fisherman Lin'do at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8615] = { title = "The Horde Needs Baked Salmon!", description = "The Ahn'Qiraj war effort is an immense undertaking, {class}. All of the materials being gathered here, whether it is metal for weapons, or food to eat, are all as important as the other. For, if you haven't eaten in days you will not have the strength to lift your axe when it matters.\n\nThus, we gather what food we can. I am collecting baked salmon, a dish that was chosen both for its sustenance and its ability to keep well. Can you aid me with this task, {class}?", objectives = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8616] = { title = "The Horde Needs More Baked Salmon!", description = "", objectives = "Bring 20 Baked Salmon to Chief Sharpclaw at the Valley of Spirits in Orgrimmar." }
WordHunterWoW_QuestEN[8619] = { title = "Morndeep the Elder", description = "", objectives = "" }
WordHunterWoW_QuestEN[8620] = { title = "The Only Prescription", description = "I should have known. My arch-enemy, Doctor Weavil, up to his old tricks! And now, thanks to your failure in Winterspring, Doctor Weavil has destroyed my book! How are you going to save the world now, hero?\n\nThe note I received stated that the only known copy of \"Draconic for Dummies: Volume II\" was ripped into 8 parts and scattered to the wind! If you somehow manage to find those missing chapters, use this magical binding to put them back together and return to me.", objectives = "Recover the 8 lost chapters of Draconic for Dummies and combine them with the Magical Book Binding and return the completed book of Draconic for Dummies: Volume II to Narain Soothfancy in Tanaris." }
WordHunterWoW_QuestEN[8621] = { title = "Stormcaller's Footguards", description = "Qiraji magic is strong and ancient.  The most powerful qiraji wield items of such might, they'd give pause even to a dragon.\n\nBring me the qiraji bindings of dominance and other minor components and I'll create a set of powerful boots for you.\n\nYou will find them useful in the fight against the enemy.", objectives = "Bring the Qiraji Bindings of Dominance, 2 Idols of the Sage, 5 Bronze Scarabs and 5 Clay Scarabs to Kandrostrasz in Ahn'Qiraj. This quest also requires Neutral faction with the Brood of Nozdormu." }
