WordHunterWoW_QuestEN[8762] = { title = "Metzen the Reindeer", description = "DISASTER has struck!  Metzen the Reindeer has been kidnapped!\n\nMetzen is one of Great-father Winter's eight reindeer - and property of Smokywood Pastures.  We believe he was carried off by that dastardly Abominable Greench, hiding out in Hillsbrad Foothills.  With the holiday season well under way, we're strapped to the coin box here!  Please - find Metzen, defeat his captors, and return him to us!", objectives = "Find Metzen the Reindeer. Use the notes provided to you for clues as to where he is being held.\nWhen you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\nReturn the Pouch of Reindeer Dust to Wulmort Jinglepocket in Ironforge once Metzen is freed." }
WordHunterWoW_QuestEN[8763] = { title = "The Hero of the Day", description = "Listen... I'm not really supposed to be telling you this, but since you're the hero of the day and all...\n\nThere's fresh holly everywhere this time of the year, but it never lasts.  We've got a machine that preserves holly - it never goes bad!  We use it to spice up the holiday... and profits during the summer!\n\nI'll let you use the preserver, but only if you're a master cook.  You'll need some deeprock salt and two, three, oh let's say five gold.  It'll net you a nice batch that's yours to keep.", objectives = "Bring 1 Deeprock Salt and 5 gold coins to any Holly Preserver machine, upon which you will receive 5 Preserved Holly." }
