WordHunterWoW_QuestEN[8945] = { title = "Dead Man's Plea", description = "I'll provide you the information you ask for, <name>.  But more pressing matters are at hand.\n\nMy beloved wife has been taken prisoner by Rivendare's undead scum.\n\nI strongly objected to her joining the Argent Dawn's foolish crusade, yet that's not of importance anymore.  You must finish what I attempted to do, you must rescue Ysida from the clutches of the Baron!", objectives = "Go into Stratholme and rescue Ysida Harmon from Baron Rivendare." }
WordHunterWoW_QuestEN[8946] = { title = "Proof of Life", description = "It is the cruelest of fates that my beloved has perished while trying to rescue me.  Yet, you claim to possess the ability to converse with him.\n\nBring him this locket as proof that I am well.  He must not linger in this world; my heart would not be able to bear it.\n\nFarewell, <name>.  I shall be in your debt always.", objectives = "Bring Ysida's Locket to Anthion Harmon in Eastern Plaguelands." }
WordHunterWoW_QuestEN[8947] = { title = "Anthion's Strange Request", description = "We didn't realize the importance of Valthalak's medallion, so it was divided along with the rest of the spoils.  The first piece was taken by a dwarf named Theldren.  I tried to retrieve it from him and he beat me within an inch of my life.  You shall have to take the fragment by force.\n\nLast I heard of him, he'd become a gladiator for the Dark Iron dwarves.  Getting him to fight you is going to present a bit of a challenge, though.\n\nGather the following materials for me.  You're going to need them.", objectives = "Bring 3 Dark Iron Bars, 20 Enchanted Leather, 3 Mooncloth and 4 Cured Rugged Hides to Anthion Harmon in the Eastern Plaguelands." }
WordHunterWoW_QuestEN[8948] = { title = "Anthion's Old Friend", description = "Theldren is not one to willingly participate in a fair fight.  I've shaped this banner to display his family colors.\n\nWith some additional sorcery, this banner shall provoke him in a way he won't be able to resist.\n\nAn old acquaintance of mine named Falrin knows the exact procedure required.  He has a particular way of... aggravating people.  You shall find him at the library in Dire Maul.", objectives = "Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul." }
WordHunterWoW_QuestEN[8949] = { title = "Falrin's Vendetta", description = "Yes, it is true that I am familiar with this enchantment you require, <class>.  Yet I'm not one to give out favors freely, even if you were sent here by an old friend.\n\nI hold nothing but hatred and contempt for our brutish ogre neighbors.  And not only them, I hate the followers of Omokk just as much as I hate those that follow King Gordok.\n\nI want you to kill them.  Kill lots of them!  Bring me the beads they carry around their neck as proof of your work.  Do this and we shall talk about your request.", objectives = "Collect 25 Ogre Warbeads from Ogres inside Dire Maul or Blackrock Spire and return to Falrin Treeshaper inside the Athenaeum in Dire Maul." }
WordHunterWoW_QuestEN[8950] = { title = "The Instigator's Enchantment", description = "I can place the enchantment you require on the banner quite easily, <name>.  Unfortunately I don't have the materials I need as it is very rarely that someone asks for this sort of charm.\n\nI will require the essence of one of the Eldreth ghosts that haunt these halls, a handful of Scholomance dark runes and some large brilliant shards.  Bring me these reagents and I shall perform this task for you.", objectives = "Bring the following to Falrin Treeshaper inside Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards." }
WordHunterWoW_QuestEN[8951] = { title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!You will receive:", objectives = "Return to Deliana in Ironforge with a set of Wildheart Boots, a Wildheart Kilt and Wildheart Spaulders." }
WordHunterWoW_QuestEN[8952] = { title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!You will receive:", objectives = "Return to Deliana in Ironforge with a set of Beaststalker's Boots, Beaststalker's Pants and Beaststalker's Mantle." }
