WordHunterWoW_QuestEN[8957] = { title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!You will receive:", objectives = "Return to Mokvar in Orgimmar with a set of Boots of Elements, Kilt of Elements and Pauldrons of Elements." }
WordHunterWoW_QuestEN[8958] = { title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!You will receive:", objectives = "Return to Deliana in Ironforge with a set of Dreadmist Sandals, Dreadmist Leggings and Dreadmist Mantle." }
WordHunterWoW_QuestEN[8959] = { title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!You will receive:", objectives = "Return to Deliana in Ironforge with a set of Boots of Valor, Legplates of Valor and Spaulders of Valor." }
WordHunterWoW_QuestEN[8960] = { title = "Bodley's Unfortunate Fate", description = "So we need to recover the rest of the medallion?  Finding Bodley's going to be a bit of a headache.  He went back to Blackrock Mountain to attempt to re-enter Blackrock Spire and never came back.\n\nI'd suggest taking the goblin's ghost revealing device with you, as I fear the worst might have happened.", objectives = "Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire." }
WordHunterWoW_QuestEN[8961] = { title = "Three Kings of Flame", description = "In order to summon Lord Valthalak we're first going to need to gather the other two-thirds of the amulet. To do that we need to get a brazier and some special coals to burn in it.\n\nThere are three nobles of fire, Lord Incedius in Blackrock Depths, Pyroguard Emberseer in Blackrock Spire and The Duke of Cynders in Silithus, with what we need. Collect from each a piece of their remains, and then return to me with a Hallowed Brazier, which can be purchased from the Argent Dawn if you are honored by them.", objectives = "Gather the Incendicite of Incendius, the Ember of Emberseer and the Cinder of Cynders, along with a Hallowed Brazier, and return them to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8962] = { title = "Components of Importance", description = "<class>, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.", objectives = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8963] = { title = "Components of Importance", description = "<class>, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.", objectives = "Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8964] = { title = "Components of Importance", description = "<class>, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.\n\nThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.", objectives = "Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8965] = { title = "Components of Importance", description = "<class>, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.", objectives = "Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8966] = { title = "The Left Piece of Lord Valthalak's Amulet", description = "My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.\n\nLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.", objectives = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning." }
WordHunterWoW_QuestEN[8967] = { title = "The Left Piece of Lord Valthalak's Amulet", description = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.\n\nShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.", objectives = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning." }
WordHunterWoW_QuestEN[8968] = { title = "The Left Piece of Lord Valthalak's Amulet", description = "The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the left piece of Lord Valthalak's amulet with them. Good riddance, I say, but we need that piece back.\n\nFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.\n\nIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.", objectives = "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning." }
WordHunterWoW_QuestEN[8969] = { title = "The Left Piece of Lord Valthalak's Amulet", description = "Now we have what we need, so it's time to discuss who it is that you'll be summoning.\n\nKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.\n\nBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.", objectives = "Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning." }
WordHunterWoW_QuestEN[8970] = { title = "I See Alcaz Island In Your Future...", description = "As I was saying, <class>, in my living years I flirted with becoming a diviner. But, there really wasn't as much profit in it as you might imagine, mostly because it's dangerous and the reagents are rare and expensive. However, I do know enough to be able to pinpoint the final piece of the amulet, and the spirit of my former comrade along with it.\n\nThis is where you come in, <name>. I need you to go to Alcaz Island off the coast of Dustwallow Marsh and collect Bloodkelp from the Strashaz naga that live there.", objectives = "Gather 20 Bloodkelp from the Strashaz naga and then return to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8977] = { title = "Return to Deliana", description = "It's been great working with you, <name>.  Here is the finished product.\n\nI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Extra-Dimensional Ghost Revealer to Deliana in Ironforge." }
WordHunterWoW_QuestEN[8978] = { title = "Return to Mokvar", description = "It's been great working with you, <name>.  Here is the finished product.\n\nI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!", objectives = "Return to Mokvar in Orgrimmar with the Extra-Dimensional Ghost Revealer." }
WordHunterWoW_QuestEN[8979] = { title = "Fenstad's Hunch", description = "I believe I know the cause of this recent behavior. Have you smelled the new fragrance on the wind, over the stink of the canals? The new colognes and perfumes that have come into fashion?\n\nOur thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to my friend, Apothecary Zinge. The Royal Apothecary Society will find the truth.\n\n I will reimburse you for their purchase when you return.", objectives = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Apothecary Zinge in the Undercity's Apothecarium." }
WordHunterWoW_QuestEN[8980] = { title = "Zinge's Assessment", description = "This is unexpected. It looks like Fenstad might be on to something after all. I found traces of substances used in mind control potions.\n\nIt isn't unheard of for perfumes to have some of this, but a few of the ingredients I detected... This is serious alchemy, along the abilities of a member of the Royal Apothecary Society.", objectives = "Return to Fenstad Argyle outside the bank in the Undercity." }
WordHunterWoW_QuestEN[8981] = { title = "Gift Giving", description = "", objectives = "" }
WordHunterWoW_QuestEN[8982] = { title = "Tracing the Source", description = "We must find who the supplier is. I noticed Apothecary Katrina with a bottle of the perfume tucked in her pack. She told me that she purchased it from Norman, the innkeeper.", objectives = "Speak with Innkeeper Norman in the Undercity." }
WordHunterWoW_QuestEN[8983] = { title = "Tracing the Source", description = "Something's wrong with my product? Well, I've never seen so many people wanting something so badly.\n\nI bought my supply from a merchant named Mara Rennick. She's new in town.\n\nShe mentioned she had some goods she had to deliver to the tailor in the Magic Quarter.", objectives = "Speak with Mara Rennick at the tailor's shop in the Undercity's Mage Quarter." }
WordHunterWoW_QuestEN[8984] = { title = "The Source Revealed", description = "Look, the actions of a rogue apothecary are not my concern. If he's undermining our efforts, then let me be the first to point you in the right direction.\n\nIf he's innocent, then he's got nothing to hide, right?\n\nI purchased the goods from Apothecary Staffron Lerent. He's working in a secluded area past Ravenholdt Manor in the hills over Hillsbrad. To be honest with you, I thought he was a little odd.", objectives = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills past Ravenholdt Manor." }
WordHunterWoW_QuestEN[8985] = { title = "More Components of Importance", description = "<class>, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.You will be able to choose one of these rewards:", objectives = "Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8986] = { title = "More Components of Importance", description = "<class>, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.", objectives = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8987] = { title = "More Components of Importance", description = "<class>, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.\n\nThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.You will be able to choose one of these rewards:", objectives = "Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8988] = { title = "More Components of Importance", description = "<class>, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.", objectives = "Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8989] = { title = "The Right Piece of Lord Valthalak's Amulet", description = "My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.\n\nLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.", objectives = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning." }
WordHunterWoW_QuestEN[8990] = { title = "The Right Piece of Lord Valthalak's Amulet", description = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.\n\nShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning." }
WordHunterWoW_QuestEN[8991] = { title = "The Right Piece of Lord Valthalak's Amulet", description = "The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the right piece of Lord Valthalak's amulet with them. Good riddance, I say, but we need that piece back.\n\nFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.\n\nIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning." }
WordHunterWoW_QuestEN[8992] = { title = "The Right Piece of Lord Valthalak's Amulet", description = "Now we have what we need, so it's time to discuss who it is that you'll be summoning next.\n\nKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.\n\nBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.", objectives = "Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning." }
WordHunterWoW_QuestEN[8993] = { title = "Gift Giving", description = "", objectives = "" }
WordHunterWoW_QuestEN[8994] = { title = "Final Preparations", description = "We're nearly there, <class>. All that is left is to retrieve a few more components so that I can attune the brazier and enable it to beckon forth Lord Valthalak.\n\nTo begin I must ask you to journey forth into Blackrock Spire and slay the orcs therein. They wear bracers that contain trace metals that I will need, so I'll need more than a few to extract the right amount out of them. Then, to complete the imbuing process, you'll need to bring me a Flask of Supreme Power.\n\nGood luck, <name>!", objectives = "Gather 40 Blackrock Bracers and acquire a Flask of Supreme Power. Return them to Bodley inside Blackrock Mountain." }
WordHunterWoW_QuestEN[8995] = { title = "Mea Culpa, Lord Valthalak", description = "All is now ready, <name>.\n\nWhen alive, Lord Valthalak used to inhabit what is now The Beast's chamber. Go there and use the Brazier of Beckoning to summon forth Lord Valthalak. It will reincorporate him, so he'll have to be killed again. I'd take care of The Beast first, and be sure take enough friends along to survive the upper portion of Blackrock Spire.\n\nOnce you've dispatched Valthalak, use the amulet on his corpse. With his spirit reunified, he'll likely want his amulet back, as well.\n\nGood luck!", objectives = "Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak." }
WordHunterWoW_QuestEN[8996] = { title = "Return to Bodley", description = "I will ignore your impertinence this time, <class>, because you have done a noble thing today; returning the rest of my stolen spirit to me. Despite your obviously weak nature, <race>, you have shown courage where those that stole from me did not, and probably never could!\n\nReturn to them, before I change my mind and slay you where you stand. Go back and tell them that they are safe... for now.", objectives = "Return to Bodley inside Blackrock Mountain and give him the Brazier of Beckoning." }
WordHunterWoW_QuestEN[8997] = { title = "Back to the Beginning", description = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.\n\nGo, before I start to cry. Go back to Deliana in Ironforge and tell her what's happened.", objectives = "Speak with Deliana at The High Seat in Ironforge." }
WordHunterWoW_QuestEN[8998] = { title = "Back to the Beginning", description = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.\n\nGo, before I start to cry. Go back to Mokvar in Orgrimmar and tell him what's happened.Upon completion of this quest you will gain:", objectives = "Speak with Mokvar at Grommash Hold in Orgrimmar's Valley of Wisdom." }
WordHunterWoW_QuestEN[8999] = { title = "Saving the Best for Last", description = "That's an amazing story, <name>! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.You will receive:", objectives = "Give Deliana your Wildheart Cowl and Wildheart Vest." }
WordHunterWoW_QuestEN[9000] = { title = "Saving the Best for Last", description = "That's an amazing story, <name>! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", objectives = "Give Deliana your Beaststalker's Cap and Beaststalker's Tunic." }
